// Type: Operation.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Operation {
    Cancel(OperationCancel),
    MoveTask(OperationMove),
    Amend(Box<OperationAmend>),
    Release(OperationRelease),
    Message(OperationMessage),
    Stop(OperationStop),
}

// Record: Operation.
impl Record for Operation {
    type Limits = Limits;
    const TAIL: Path = paths::OPERATION_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 359)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 359)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Cancel(value) => { field::put(out, &[0], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::MoveTask(value) => { field::put(out, &[1], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Amend(value) => { field::put(out, &[2], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Release(value) => { field::put(out, &[3], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Message(value) => { field::put(out, &[4], paths::OPERATION_TAG)?; value.write(limits, out) },
            Self::Stop(value) => { field::put(out, &[5], paths::OPERATION_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OPERATION_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Cancel(OperationCancel::read(limits, reader)?)),
            1 => Ok(Self::MoveTask(OperationMove::read(limits, reader)?)),
            2 => Ok(Self::Amend(Box::new(OperationAmend::read(limits, reader)?))),
            3 => Ok(Self::Release(OperationRelease::read(limits, reader)?)),
            4 => Ok(Self::Message(OperationMessage::read(limits, reader)?)),
            5 => Ok(Self::Stop(OperationStop::read(limits, reader)?)),
            6..=u8::MAX => Err(Problem { path: paths::OPERATION_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

