// Type: Running.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Running {
    Stays,
    Moves,
}

// Record: Running.
impl Record for Running {
    type Limits = Limits;
    const TAIL: Path = paths::RUNNING_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 434)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 434)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Stays => field::put(out, &[0], paths::RUNNING_TAG),
            Self::Moves => field::put(out, &[1], paths::RUNNING_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::RUNNING_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Stays),
            1 => Ok(Self::Moves),
            2..=u8::MAX => Err(Problem { path: paths::RUNNING_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

