// Type: Malformed.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Malformed {
    Name(MalformedName),
    Cycle,
    AsAllowedTwice,
    Conversation,
    ProposedAsAllowed,
    EndedBy,
    Settings(MalformedSettings),
    SettingsUnchanged,
    Running,
}

// Record: Malformed.
impl Record for Malformed {
    type Limits = Limits;
    const TAIL: Path = paths::MALFORMED_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 847)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 847)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Name(value) => { field::put(out, &[0], paths::MALFORMED_TAG)?; value.write(limits, out) },
            Self::Cycle => field::put(out, &[1], paths::MALFORMED_TAG),
            Self::AsAllowedTwice => field::put(out, &[2], paths::MALFORMED_TAG),
            Self::Conversation => field::put(out, &[3], paths::MALFORMED_TAG),
            Self::ProposedAsAllowed => field::put(out, &[4], paths::MALFORMED_TAG),
            Self::EndedBy => field::put(out, &[5], paths::MALFORMED_TAG),
            Self::Settings(value) => { field::put(out, &[6], paths::MALFORMED_TAG)?; value.write(limits, out) },
            Self::SettingsUnchanged => field::put(out, &[7], paths::MALFORMED_TAG),
            Self::Running => field::put(out, &[8], paths::MALFORMED_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::MALFORMED_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Name(MalformedName::read(limits, reader)?)),
            1 => Ok(Self::Cycle),
            2 => Ok(Self::AsAllowedTwice),
            3 => Ok(Self::Conversation),
            4 => Ok(Self::ProposedAsAllowed),
            5 => Ok(Self::EndedBy),
            6 => Ok(Self::Settings(MalformedSettings::read(limits, reader)?)),
            7 => Ok(Self::SettingsUnchanged),
            8 => Ok(Self::Running),
            9..=u8::MAX => Err(Problem { path: paths::MALFORMED_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

