// Type: AccountHostWhy.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum AccountHostWhy {
    NotInContact,
    Lost,
    Failed,
}

// Record: AccountHostWhy.
impl Record for AccountHostWhy {
    type Limits = Limits;
    const TAIL: Path = paths::ACCOUNT_HOST_WHY_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1000)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 1000)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::NotInContact => field::put(out, &[0], paths::ACCOUNT_HOST_WHY_TAG),
            Self::Lost => field::put(out, &[1], paths::ACCOUNT_HOST_WHY_TAG),
            Self::Failed => field::put(out, &[2], paths::ACCOUNT_HOST_WHY_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ACCOUNT_HOST_WHY_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::NotInContact),
            1 => Ok(Self::Lost),
            2 => Ok(Self::Failed),
            3..=u8::MAX => Err(Problem { path: paths::ACCOUNT_HOST_WHY_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

